package command_test

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"strings"
	"testing"

	"github.com/f5dt1artum/shellsmith/command"
)

// recorded captures what a handler observed.
type recorded struct {
	path   []string
	args   []string
	stdout string
	stderr string
}

func newNode(t *testing.T, name string, aliases []string, h command.Handler) *command.Command {
	t.Hper()
	c, err := command.New(name, "desc", aliases, h)
	if err != nil {
		t.Fatalf("New(%q) unexpected error: %v", name, err)
	}
	return c
}

func TestNewValidatesNames(t *testing.T) {
	valid := []string{"a", "abc", "A1", "a_b", "a-b", "x-y_z-9", "_x", "123"}
	for _, name := range valid {
		if _, err := command.New(name, "", nil, nil); err != nil {
			t.Errorf("New(%q) unexpected error: %v", name, err)
		}
	}
	invalid := []string{"", "-x", "-", "ab!", "a b", "a.b", "a/b", "café", "世界", "x--", " leading", "trailing "}
	for _, name := range invalid {
		_, err := command.New(name, "", nil, nil)
		if !errors.Is(err, command.ErrInvalidName) {
			t.Errorf("New(%q) error = %v, want ErrInvalidName", name, err)
		}
		if err != nil && !strings.Contains(err.Error(), name) {
			t.Errorf("error %q does not carry the offending name %q", err, name)
		}
	}
}

func TestNewRejectsDuplicateAliases(t *testing.T) {
	cases := [][]string{
		{"v", "v"},        // alias repeated
		{"run", "start"},  // alias shadows primary name "start"
		{"x", "y", "x"},   // alias repeated non-adjacently
	}
	primary := []string{"v", "start", "p"}
	for i, aliases := range cases {
		_, err := command.New(primary[i], "", aliases, nil)
		if !errors.Is(err, command.ErrNameConflict) {
			t.Errorf("case %d: error = %v, want ErrNameConflict", i, err)
		}
	}
}

func TestAddRejectsNil(t *testing.T) {
	root := newNode(t, "root", nil, nil)
	_, err := root.Add(nil)
	if !errors.Is(err, command.ErrInvalidCommand) {
		t.Fatalf("Add(nil) error = %v, want ErrInvalidCommand", err)
	}
}

func TestAddRejectsConflictsAndPreservesOrder(t *testing.T) {
	root := newNode(t, "root", nil, nil)

	start := newNode(t, "start", []string{"up", "run"}, nil)
	if _, err := root.Add(start); err != nil {
		t.Fatalf("Add start: %v", err)
	}
	stop := newNode(t, "stop", []string{"down"}, nil)
	if _, err := root.Add(stop); err != nil {
		t.Fatalf("Add stop: %v", err)
	}

	conflicts := []struct {
		name    string
		aliases []string
	}{
		{"start", nil},        // primary duplicates primary
		{"up", nil},           // primary duplicates alias
		{"other", []string{"run"}}, // alias duplicates alias
		{"other", []string{"stop"}},// alias duplicates primary
		{"other", []string{"DOWN"}},// case-sensitive: fine, must NOT conflict
	}
	for i, tc := range conflicts {
		c, err := command.New(tc.name, "", tc.aliases, nil)
		if err != nil {
			t.Fatalf("case %d: New: %v", i, err)
		}
		_, err = root.Add(c)
		wantConflict := tc.name != "other" || (len(tc.aliases) == 1 && tc.aliases[0] != "DOWN")
		if i == 4 {
			wantConflict = false
		}
		if wantConflict && !errors.Is(err, command.ErrNameConflict) {
			t.Errorf("case %d (%s): error = %v, want ErrNameConflict", i, tc.name, err)
		}
		if !wantConflict && err != nil {
			t.Errorf("case %d (%s): unexpected error %v", i, tc.name, err)
		}
	}
}

func TestAddFailureDoesNotMutateTree(t *testing.T) {
	var got recorded
	h := func(_ context.Context, path []string, args []string, stdout, stderr w) error {
		// replaced below
		return nil
	}
	_ = h

	root := newNode(t, "root", nil, nil)
	leafHandler := func(_ context.Context, path []string, args []string, stdout, stderr w2) error { return nil }
	_ = leafHandler

	good := newNode(t, "good", nil, func(_ context.Context, path []string, args []string, stdout, stderr io.Writer) error {
		return nil
	})
	if _, err := root.Add(good); err != nil {
		t.Fatal(err)
	}

	bad, err := command.New("good", nil, nil, nil) // conflicts
	if err != nil {
		t.Fatal(err)
	}
	if _, err := root.Add(bad); !errors.Is(err, command.ErrNameConflict) {
		t.Fatalf("conflicting Add error = %v, want ErrNameConflict", err)
	}
	// Rejected node is still unattached and can join another parent.
	other := newNode(t, "other", nil, nil)
	if _, err := other.Add(bad); err != nil {
		t.Errorf("rejected node should remain unattached: %v", err)
	}

	// Existing registration still resolves, rejected name does not.
	var called bool
	good2, _ := command.New("good2", "", nil, func(context.Context, []string, []string, io.Writer, io.Writer) error {
		called = true
		return nil
	})
	_ = good2
	if err := root.Execute(context.Background(), []string{"good2"}, io.Discard, io.Discard); !errors.Is(err, command.ErrUnknownCommand) {
		t.Errorf("unregistered node should be unknown, got %v", err)
	}
	if called {
		t.Error("handler of rejected node must not run")
	}
}

func TestAddRejectsAttachedNode(t *testing.T) {
	root1 := newNode(t, "root1", nil, nil)
	root2 := newNode(t, "root2", nil, nil)
	child := newNode(t, "child", nil, nil)
	if _, err := root1.Add(child); err != nil {
		t.Fatal(err)
	}
	if _, err := root1.Add(child); !errors.Is(err, command.ErrAlreadyAttached) {
		t.Errorf("re-adding to same parent error = %v", err)
	}
	if _, err := root2.Add(child); !errors.Is(err, command.ErrAlreadyAttached) {
		t.Errorf("adding to second parent error = %v", err)
	}
}

