	if child.parent != nil {
		return c, fmt.Errorf("%w: %q", ErrAlreadyAttached, child.name)
	}
	for _, taken := range c.names() {
		for _, offered := range child.names() {
			if taken == offered {
				return c, fmt.Errorf("%w: %q", ErrNameConflict, offered)
			}
		}
