		if len(args) == 0 {
			break
		}
		next, ok := current.findChild(args[0])
		if !ok {
			return &LookupError{Path: append([]string(nil), path...), Arg: args[0]}
		}
		current = next
		path = append(path, current.name)
		args = args[1:]
	}
